import{_ as r,o as e,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-08-12 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-08-12 :: Ceph Orchestration Meeting","date":"2019-08-12T00:00:00.000Z","updated":"2019-08-12T00:00:00.000Z","tags":["Ceph","Orchestrators","Rook","Kubernetes","Storage Orchestration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-12_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-08-12_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),n={name:"posts/2019/2019-08-12_-_-_Ceph_Orchestration_Meeting.md"};function i(l,t,a,g,_,p){return e(),o("div",null,[...t[0]||(t[0]=[s("<p>会议纪要</p><p><strong>会议时间</strong>： 2019年8月12日 <strong>参会人员</strong>： [请填写参会人员名单] <strong>会议主题</strong>： Orchestrators 团队周会 <strong>会议内容</strong>：</p><p><strong>1. 团队成员近况分享</strong></p><ul><li>成员们分享了近期的工作和生活情况，包括新办公地点的搬迁和新环境的适应。</li><li>提到由于搬迁，近期工作较为繁忙，但整体氛围良好。</li></ul><p><strong>2. 主要议题讨论</strong></p><ul><li><strong>Rook 的 OSD 集成</strong>： 成员介绍了 Rook 的 OSD 在 Peavey 上的集成进展，已准备合并代码，预计 CI 通过后即可合并。</li><li><strong>Dashboard 展示</strong>： 讨论了如何将 OSD 集成信息展示在 Dashboard 上，以便用户了解存储类别的选择和使用方式。计划在周三进行讨论，由 Bangalore 的开发团队参加。</li><li><strong>CSI 驱动默认启用</strong>： 成员提到 CSI 驱动默认启用，对编排方面的影响不大。</li><li><strong>zrd 验证最终审查</strong>： 成员介绍了 zrd 验证的最终审查进展，目前仍在跟踪 CI 问题，预计很快完成。</li><li><strong>事件报告</strong>： 成员介绍了将事件报告引入 Kubernetes 的 PR，但尚未进行详细审查。</li><li><strong>持久卷云支持</strong>： 讨论了持久卷云支持的实现方式，由于环境差异，需要进一步研究如何正确实现。</li></ul><p><strong>3. 决定事项</strong></p><ul><li>计划在周三进行 Dashboard 展示方式的讨论。</li><li>加快 zrd 验证最终审查的进度。</li><li>对事件报告 PR 进行审查。</li><li>研究持久卷云支持的实现方式。</li></ul><p><strong>4. 后续行动计划</strong></p><ul><li>成员们将根据讨论结果，继续推进相关项目的开发工作。</li><li>定期进行团队周会，讨论项目进展和问题。</li></ul><p><strong>5. 其他事项</strong></p><ul><li>无。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph 领域的英文关键词，如 Rook、OSD、Peavey、Dashboard、CSI、zrd、Kubernetes 等。</li></ul>",14)])])}const h=r(n,[["render",i]]);export{c as __pageData,h as default};
